{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall implement a multi-layer safety architecture including passive, active, and functional safety mechanisms.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall execute a Minimal Risk Maneuver within 5 seconds upon detecting critical system failures to ensure safety.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-02", "EFF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall continuously monitor Operational Design Domain compliance and issue timely human takeover requests.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-03", "EFF-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall allow relaxation of smoothness constraints during emergencies with a jerk limit of 0.75 m/s³ while monitoring energy consumption.",
      "quality_axes": ["Safety", "Efficiency", "Sustainability"],
      "derived_from": ["SAF-04", "EFF-07", "GRN-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall satisfy curvature constraints to prevent rollover during maneuvers.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints reliably.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["SAF-06", "EFF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall implement end-to-end data encryption for all user data transmitted.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall enforce role-based access control to protect user permissions.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall log all access and modifications to critical data for auditability.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall implement a multi-layer safety architecture that guarantees active monitoring.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall document all safety and compliance-related decisions for accountability.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-07"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall ensure compliance with Apollo Pilot Safety Report and EM Motion Planner specifications.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The system shall provide timely HMI warnings to request human takeover when ODD compliance is at risk.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall minimize energy consumption during operation by optimizing path and speed profiles.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall implement lifecycle assessments for all components to ensure sustainability.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-03"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
  "conflict_resolutions": [
    {
